-- MP-0031: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='amanah' and type='party') then raise exception 'MP-0031: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0031: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('amirudin-shari','rodziah-ismail','mohd-sany-hamzan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0031: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('gombak','ampang','hulu langat') and slug not in ('amirudin-shari','rodziah-ismail','mohd-sany-hamzan')) then raise exception 'MP-0031: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0031:%' and (m.source_type <> 'editorial' or e.slug not in ('amirudin-shari','rodziah-ismail','mohd-sany-hamzan') or m.import_key not like 'MP-0031:' || e.slug || ':%')) then raise exception 'MP-0031: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'amirudin-shari','Amirudin Shari','government','Menteri Besar of Selangor; Member of the Dewan Rakyat','Gombak','Selangor','Amirudin Shari represents Gombak, Selangor, in the Dewan Rakyat. Current role: Menteri Besar of Selangor; Member of the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4137','/portraits/amirudin-shari.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P098.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4137"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}, {"label": "Selangor · current Menteri Besar and flood response, 6 November 2026", "url": "https://mediaselangor.com/ms/2026/11/405438"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'rodziah-ismail','Rodziah Ismail','government','Member of the Dewan Rakyat','Ampang','Selangor','Rodziah Ismail represents Ampang, Selangor, in the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4138','/portraits/rodziah-ismail.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P099.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4138"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-sany-hamzan','Mohd Sany Hamzan','government','Member of the Dewan Rakyat','Hulu Langat','Selangor','Mohd Sany Hamzan represents Hulu Langat, Selangor, in the Dewan Rakyat. A AMANAH member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4140','/portraits/mohd-sany-hamzan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P101.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4140"}, {"label": "AMANAH · election director, 15 October 2026", "url": "https://www.malaysiakini.com/news/887066-amanah-reps-open-to-selangor-harapan-bersatu-pact-wider-political-cooperation"}]'::jsonb from public.entities parent where parent.slug='amanah' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('amirudin-shari','rodziah-ismail','mohd-sany-hamzan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0031: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0031:amirudin-shari:coastal-embankment-monitoring','Intensify coastal embankment monitoring during the November high tides','Environment','in_progress',null,null,null,null,'2026-11-06','https://mediaselangor.com/ms/2026/11/405438','Amirudin reported heightened monitoring from Sabak Bernam through Kuala Selangor to Morib, alongside disaster preparedness and evacuation arrangements.','In progress reflects the 6 November operational report. It does not certify that all embankments were strengthened or that later flooding was prevented. The tide forecast is not a project completion deadline.','2026-11-09','editorial',false from public.entities e where e.slug='amirudin-shari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0031:amirudin-shari:puncak-alam-development-review','Review development approvals and inspect projects after the Puncak Alam floods','Governance',null,null,null,'2026-11-06','https://berita.rtm.gov.my/kes/senarai-berita-kes/senarai-artikel/banjir-selangor-kenal-pasti-langkah-mitigasi-kawal-aliran-air/',null,null,'Amirudin said the state would re-examine development approvals and investigate two projects around Saujana Aman following flash flooding.','The review and investigations are announced steps. Their conclusions, remedial construction and resolution of the wider flood problem were not established.','2026-11-09','editorial',false from public.entities e where e.slug='amirudin-shari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

